  seedParticipants: async () => {
    if (!isFirebaseReady || !db) return;

    try {
      const snap = await db.collection('participants').get();

      // If participants already exist, don't seed
      if (snap.size > 0) {
        console.log('Participants already exist in Firestore');
        return;
      }

