// Fair comparison and fitness metrics

const FitnessMetrics = {
  // Calculate BMI from weight (lbs) and height (inches)
  bmi: (weight_lbs, height_inches) => {
    return (weight_lbs / (height_inches * height_inches)) * 703;
  },

  // Calculate absolute pounds lost
  lbsLost: (start_weight, current_weight) => {
    return start_weight - current_weight;
  },

  // Calculate percentage of body weight lost (PRIMARY metric for ranking)
  percentLost: (start_weight, current_weight) => {
    const lost = FitnessMetrics.lbsLost(start_weight, current_weight);
    return (lost / start_weight) * 100;
  },

  // Calculate BMI change
  bmiChange: (start_weight, start_height_inches, current_weight) => {
    const startBmi = FitnessMetrics.bmi(start_weight, start_height_inches);
    const currentBmi = FitnessMetrics.bmi(current_weight, start_height_inches);
    return startBmi - currentBmi;
  },

  // Get all metrics as an object
  getMetrics: (participant, current_weight) => {
    const lbs_lost = FitnessMetrics.lbsLost(participant.start_weight_lbs, current_weight);
    const percent_lost = FitnessMetrics.percentLost(participant.start_weight_lbs, current_weight);
    const start_bmi = FitnessMetrics.bmi(participant.start_weight_lbs, participant.height_inches);
    const current_bmi = FitnessMetrics.bmi(current_weight, participant.height_inches);
    const bmi_change = start_bmi - current_bmi;

    return {
      lbs_lost: lbs_lost.toFixed(1),
      percent_lost: percent_lost.toFixed(2),
      start_bmi: start_bmi.toFixed(1),
      current_bmi: current_bmi.toFixed(1),
      bmi_change: bmi_change.toFixed(2)
    };
  },

  // Format percent for display
  formatPercent: (value) => {
    return parseFloat(value).toFixed(2) + '%';
  },

  // Format pounds for display
  formatPounds: (value) => {
    const num = parseFloat(value);
    return (num >= 0 ? '+' : '') + num.toFixed(1) + ' lbs';
  },

  // Format BMI for display
  formatBmi: (value) => {
    return parseFloat(value).toFixed(1);
  }
};

input.content:
/* ============================================
   Bear Paws Fitness Tracker - Dark Theme
   Mobile-first
   ============================================ */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  /* Accent */
  --color-primary: #60a5fa;
  --color-primary-strong: #3b82f6;
  --color-primary-dim: rgba(96, 165, 250, 0.14);

  /* Semantic - success is "moving the right way", danger is "wrong way" */
  --color-success: #34d399;
  --color-danger: #f87171;
  --color-warning: #fbbf24;

  /* Surfaces */
  --color-bg: #0b1017;
  --color-surface: #131a24;
  --color-surface-2: #1b2532;
  --color-surface-3: #232f3f;
  --color-border: #2b3849;
  --color-border-soft: #212c3a;

  /* Text */
  --color-text: #e8edf5;
  --color-text-light: #94a3b8;
  --color-text-dim: #64748b;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.45);

  --spacing-xs: 0.5rem;
  --spacing-sm: 0.75rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;

  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;

  color-scheme: dark;
}

html, body {
  min-height: 100%;
  font-family: var(--font-family);
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
}

/* ---- Header ---- */
.header {
  background: linear-gradient(135deg, #17233a, #0e1520);
  border-bottom: 1px solid var(--color-border);
  color: var(--color-text);
  padding: var(--spacing-lg);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  letter-spacing: -0.5px;
}

.loading {
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
  display: none;
}

.loading.active {
  display: block;
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

/* ---- Navigation Tabs ---- */
.nav-tabs {
  display: flex;
  gap: 0;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  padding: 0 var(--spacing-md);
  position: sticky;
  top: 73px;
  z-index: 50;
}

.nav-tab {
  flex: 1;
  min-width: 100px;
  padding: var(--spacing-md) var(--spacing-sm);
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-text-light);
  transition: color 0.15s ease, background 0.15s ease;
}

.nav-tab:hover {
  color: var(--color-text);
  background: var(--color-surface-2);
}

.nav-tab.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

@media (max-width: 640px) {
  .nav-tabs { padding: 0 var(--spacing-sm); top: 65px; }
  .nav-tab { padding: var(--spacing-sm) var(--spacing-xs); font-size: 0.75rem; }
}

/* ---- Pages ---- */
.pages-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.page { display: none; animation: fadeIn 0.2s ease; }
.page.active { display: block; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(2px); }
  to { opacity: 1; transform: none; }
}

.page-content {
  background: var(--color-surface);
  border: 1px solid var(--color-border-soft);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  box-shadow: var(--shadow-sm);
}

.page-content h2 {
  margin-bottom: var(--spacing-lg);
  font-size: var(--font-size-2xl);
  color: var(--color-text);
}

.page-content h3 {
  margin-bottom: var(--spacing-md);
  font-size: var(--font-size-lg);
  color: var(--color-text);
}

.loading-text {
  text-align: center;
  color: var(--color-text-light);
  padding: var(--spacing-xl);
}

/* ---- Cards ---- */
.card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border-soft);
  border-radius: var(--radius-md);
  padding: var(--spacing-md);
  margin-bottom: var(--spacing-md);
}

.card.highlight {
  border-left: 3px solid var(--color-primary);
  background: linear-gradient(to right, var(--color-primary-dim), var(--color-surface-2) 60%);
}

.card h3, .card h4 {
  margin-bottom: var(--spacing-sm);
  color: var(--color-text);
}

.card h4 { font-size: var(--font-size-base); }

.card p { color: var(--color-text-light); font-size: var(--font-size-sm); }
.card p + p { margin-top: 0.25rem; }

.card-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--spacing-md);
  padding: 0.3rem 0;
  font-size: var(--font-size-sm);
}

.card-label { color: var(--color-text-light); font-weight: 500; }

.card-value {
  font-weight: 700;
  color: var(--color-text);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.card-value.primary { color: var(--color-primary); font-size: var(--font-size-lg); }
.card-value.success { color: var(--color-success); }
.card-value.danger  { color: var(--color-danger); }
.card-value.warning { color: var(--color-warning); }
.card-value.muted   { color: var(--color-text-light); }

.divider {
  height: 1px;
  background: var(--color-border);
  border: none;
  margin: var(--spacing-md) 0;
}

.section-label {
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-dim);
  font-weight: 700;
  margin-bottom: var(--spacing-xs);
}

/* ---- Forms ---- */
.form { display: flex; flex-direction: column; gap: var(--spacing-md); }
.form-group { display: flex; flex-direction: column; }

.form-group label {
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  font-size: var(--font-size-sm);
  color: var(--color-text);
}

.form-hint {
  font-size: 0.75rem;
  color: var(--color-text-dim);
  margin-top: 0.3rem;
}

.required-star { color: var(--color-danger); }

.form-group input,
.form-group select,
.form-group textarea,
.inline-input {
  padding: var(--spacing-sm) var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  color: var(--color-text);
  background: var(--color-surface-3);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  width: 100%;
}

.form-group input::placeholder,
.form-group textarea::placeholder,
.inline-input::placeholder {
  color: var(--color-text-dim);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus,
.inline-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-primary-dim);
}

.form-group textarea { min-height: 84px; resize: vertical; }

/* Date pickers need a light calendar icon on dark */
input[type="date"]::-webkit-calendar-picker-indicator {
  filter: invert(0.8);
  cursor: pointer;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-md);
}

@media (max-width: 640px) {
  .form-row { grid-template-columns: 1fr; }
}

.form-checkbox {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  cursor: pointer;
}

.form-checkbox input {
  cursor: pointer;
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: var(--color-primary-strong);
}

.form-checkbox label,
.form-checkbox span { margin: 0; cursor: pointer; user-select: none; }

.form-box {
  background: var(--color-surface-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--spacing-md);
  margin-bottom: var(--spacing-md);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

/* ---- Buttons ---- */
.btn {
  padding: var(--spacing-sm) var(--spacing-lg);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font-size: var(--font-size-base);
  font-weight: 600;
  cursor: pointer;
  transition: filter 0.15s ease, background 0.15s ease, border-color 0.15s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-xs);
  font-family: var(--font-family);
}

.btn-primary { background: var(--color-primary-strong); color: #0b1017; }
.btn-primary:hover { filter: brightness(1.12); }

.btn-secondary {
  background: var(--color-surface-3);
  color: var(--color-text);
  border-color: var(--color-border);
}
.btn-secondary:hover { border-color: var(--color-primary); color: var(--color-primary); }

.btn-success { background: var(--color-success); color: #06231a; }
.btn-success:hover { filter: brightness(1.1); }

.btn-danger { background: var(--color-danger); color: #2a0b0b; }
.btn-danger:hover { filter: brightness(1.1); }

.btn-small { padding: 0.4rem 0.7rem; font-size: var(--font-size-sm); }
.btn-block { width: 100%; }

/* ---- Tables ---- */
.table-scroll {
  overflow-x: auto;
  border: 1px solid var(--color-border-soft);
  border-radius: var(--radius-md);
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--font-size-sm);
  min-width: 720px;
}

.table th {
  background: var(--color-surface-3);
  padding: var(--spacing-sm) var(--spacing-md);
  text-align: left;
  font-weight: 700;
  color: var(--color-text-light);
  white-space: nowrap;
  border-bottom: 1px solid var(--color-border);
}

.table td {
