    workoutDetails.classList.toggle('hidden', !workedOutCheckbox.checked);
    workoutMinutes.value = log && log.workout_minutes ? log.workout_minutes : '';
    workoutNotes.value = log && log.workout_notes ? log.workout_notes : '';
